<script>(()=>{const k='smooth-operators-theme',apply=t=>{document.body.classList.toggle('dark-mode',t==='dark');document.querySelectorAll('#theme-toggle,#theme-toggle-mobile').forEach(b=>{b.textContent=t==='dark'?'☀ Light mode':'☾ Dark mode';b.setAttribute('aria-pressed',t==='dark')})};apply(localStorage.getItem(k)||'light');document.addEventListener('click',e=>{if(e.target.closest('#theme-toggle')||e.target.closest('#theme-toggle-mobile')){const n=document.body.classList.contains('dark-mode')?'light':'dark';localStorage.setItem(k,n);apply(n)}})})();</script></body></html>